kb = env['chatroom.ai.knowledge'].create({
    'name': params['name'],
    'content_type': 'text',
    'content': params['content'],
})
kb.action_process_content()
associated_agent_name = None
association_error = None
agent_id = params.get('agent_id')
if agent_id:
    target = env['chatroom.ai.agent'].browse(agent_id)
    if not target.exists():
        association_error = f"agent_id {agent_id} does not exist"
    elif target.is_management_agent:
        association_error = (
            f"agent_id {agent_id} is the management agent. Knowledge bases "
            "can only be associated to business agents."
        )
    else:
        target.write({'knowledge_ids': [(4, kb.id)]})
        associated_agent_name = target.name
msg = f'Knowledge base "{kb.name}" created with {kb.char_count} characters'
if associated_agent_name:
    msg += f', associated to agent "{associated_agent_name}"'
elif association_error:
    msg += f'. NOT associated ({association_error}).'
result = {
    'success': True,
    'knowledge_id': kb.id,
    'name': kb.name,
    'chars': kb.char_count,
    'associated_agent': associated_agent_name,
    'association_error': association_error,
    'message': msg,
}

kb = env['chatroom.ai.knowledge'].browse(params.get('knowledge_id'))
if not kb.exists():
    result = {'success': False, 'error': 'Knowledge base not found'}
else:
    vals = {}
    if 'name' in params:
        vals['name'] = params['name']
    if 'content' in params:
        vals['content'] = params['content']
    if vals:
        kb.write(vals)
        if 'content' in params:
            kb.action_process_content()
    result = {
        'success': True,
        'message': f'Knowledge base "{kb.name}" updated successfully',
        'chars': kb.char_count,
    }

agent = env['chatroom.ai.agent'].browse(params.get('agent_id'))
knowledge_ids = params.get('knowledge_ids', [])
if not agent.exists() or agent.is_management_agent:
    result = {'success': False, 'error': 'Agent not found'}
elif not knowledge_ids:
    result = {'success': False, 'error': 'No knowledge base IDs provided'}
else:
    agent.write({'knowledge_ids': [(4, kid) for kid in knowledge_ids]})
    result = {
        'success': True,
        'message': f'Associated {len(knowledge_ids)} knowledge base(s) to agent "{agent.name}"',
        'total_knowledge_count': len(agent.knowledge_ids),
    }

agent = env['chatroom.ai.agent'].browse(params.get('agent_id'))
knowledge_ids = params.get('knowledge_ids', [])
if not agent.exists() or agent.is_management_agent:
