agent = env['chatroom.ai.agent'].browse(params.get('agent_id'))
tool_code_names = params.get('tool_code_names', [])
if not agent.exists() or agent.is_management_agent:
    result = {'success': False, 'error': 'Agent not found or is the management agent'}
else:
    found = env['chatroom.ai.tool'].search([
        ('code_name', 'in', tool_code_names),
        ('active', '=', True),
        ('is_management_tool', '=', False),
    ])
    found_names = set(found.mapped('code_name'))
    unknown = [n for n in tool_code_names if n not in found_names]
    if unknown:
        available = env['chatroom.ai.tool'].search([
            ('active', '=', True),
            ('is_management_tool', '=', False),
        ]).mapped('code_name')
        result = {
            'success': False,
            'error': (
                f"Unknown tool code_names: {unknown}. "
                f"Call list_available_tools first; the valid code_names are: {available}."
            ),
        }
    else:
        agent.write({'tool_ids': [(4, t.id) for t in found]})
        result = {
            'success': True,
            'message': f'Added {len(found)} tool(s) to agent "{agent.name}"',
            'tools_added': [t.code_name for t in found],
            'total_tools_now': agent.tool_ids.mapped('code_name'),
        }

agent = env['chatroom.ai.agent'].browse(params.get('agent_id'))
tool_code_names = params.get('tool_code_names', [])
if not agent.exists() or agent.is_management_agent:
    result = {'success': False, 'error': 'Agent not found or is the management agent'}
else:
    to_remove = agent.tool_ids.filtered(lambda t: t.code_name in tool_code_names)
    if to_remove:
        agent.write({'tool_ids': [(3, t.id) for t in to_remove]})
    result = {
        'success': True,
        'message': f'Removed {len(to_remove)} tool(s) from agent "{agent.name}"',
        'tools_removed': [t.code_name for t in to_remove],
        'total_tools_now': agent.tool_ids.mapped('code_name'),
    }

limit = params.get('limit') or 5
try:
    limit = max(1, min(int(limit), 20))
except (TypeError, ValueError):
    limit = 5

messages = env['chatroom.message'].search(
    [('room_id', '=', room.id), ('attachment_id', '!=', False)],
    order='create_date desc',
    limit=limit,
)
result = {
    'success': True,
    'count': len(messages),
    'attachments': [
        {
            'message_id': m.id,
            'filename': m.filename or (m.attachment_id.name if m.attachment_id else ''),
            'mime_type': m.mime_type or (m.attachment_id.mimetype if m.attachment_id else ''),
            'created_at': m.create_date.isoformat() if m.create_date else None,
        }
        for m in messages
    ],
}

from odoo.addons.chatroom_ai.utils.text_extraction import extract_text_from_attachment, is_supported

message = env['chatroom.message'].browse(params.get('message_id'))
if not message.exists():
    result = {'success': False, 'error': f"Message {params.get('message_id')} not found"}
elif not message.attachment_id:
    result = {'success': False, 'error': 'That message has no attachment'}
elif message.room_id.id != room.id:
    result = {'success': False, 'error': 'Message belongs to a different room'}
else:
    att = message.attachment_id
    fname = message.filename or att.name or 'file'
    if not is_supported(fname):
        result = {
            'success': False,
            'error': f"Unsupported file type: {fname}. Supported: PDF, DOCX, XLS/XLSX, TXT, MD, CSV.",
        }
    else:
        extracted = extract_text_from_attachment(att)
        if not extracted or extracted.startswith('Error processing') or extracted == 'Unsupported file type':
            result = {
                'success': False,
                'error': f"Could not extract text from {fname}: {extracted or 'empty content'}",
            }
        else:
            kb = env['chatroom.ai.knowledge'].create({
                'name': params['name'],
                'content_type': 'file',
                'file': att.datas,
                'file_name': fname,
                'description': params.get('description'),
                'processed_content': extracted,
                'processing_status': 'success',
                'processing_message': f'Imported from chat attachment (message {message.id}): {len(extracted)} characters',
                'last_updated': fields.Datetime.now(),
            })
            associated_agent_name = None
            association_error = None
            agent_id = params.get('agent_id')
            if agent_id:
                target = env['chatroom.ai.agent'].browse(agent_id)
                if not target.exists():
                    association_error = f"agent_id {agent_id} does not exist"
                elif target.is_management_agent:
                    association_error = (
                        f"agent_id {agent_id} is the management agent. "
                        "Knowledge bases can only be associated to business "
                        "agents. Create the business agent first with "
                        "create_agent, then call associate_knowledge_to_agent."
                    )
                else:
                    target.write({'knowledge_ids': [(4, kb.id)]})
                    associated_agent_name = target.name
            msg = (
                f'Knowledge base "{kb.name}" created from {fname} '
                f'({kb.char_count} chars)'
            )
            if associated_agent_name:
                msg += f', associated to agent "{associated_agent_name}"'
            elif association_error:
                msg += (
                    f'. NOT associated yet ({association_error}). '
                    'Call associate_knowledge_to_agent later with the right agent_id.'
                )
            else:
                msg += '. Not associated to any agent yet.'
            result = {
                'success': True,
                'knowledge_id': kb.id,
                'name': kb.name,
                'chars': kb.char_count,
                'associated_agent': associated_agent_name,
                'association_error': association_error,
                'message': msg,
            }
